// Keep the released corrective set deliberately bounded at 24 stories. The
// second wildlife route broadens the environmental threat beyond the snare story.
const WILDERNESS_FIELDCRAFT_RELEASED = WILDERNESS_FIELDCRAFT_EDITORIAL_DRAFT.slice(0, 24)
  .filter(({ id }) => id !== 'the-night-bird-turn');
const BEAR_FIELDCRAFT_ADVENTURE = WILDERNESS_FIELDCRAFT_EDITORIAL_DRAFT.find(({ id }) => id === 'the-bear-at-the-berry-ridge');
export const WILDERNESS_FIELDCRAFT_GENRE_BATCH = [...WILDERNESS_FIELDCRAFT_RELEASED, ...(BEAR_FIELDCRAFT_ADVENTURE ? [BEAR_FIELDCRAFT_ADVENTURE] : [])];

export const WILDERNESS_FIELDCRAFT_GENRE_IDS = new Set(WILDERNESS_FIELDCRAFT_GENRE_BATCH.map(({ id }) => id));
